const builders: Record<SchoolTopicId, (p: Parameters) => Draft> = {
  'school-divisibility': divisibility, 'school-gcd-lcm': commonFactors,
  'school-decimals': decimals, 'school-rounding': rounding, 'school-sets': sets,
  'school-absolute-value': absoluteValue, 'school-basic-angles': angles, 'school-perimeter': perimeter,
};

function create(p: Parameters): Task {
  return { ...builders[p.topicId](p), id: `school-review-${p.topicId.slice(7)}-${p.level}-${p.serial}`, topicId: p.topicId,
    level: p.level, skill: p.topicId, commonError: { ...errors[p.topicId] },
    generation: { version: 'review-2026.2', serial: p.serial, templateIndex: (p.level - 1) * 2 + p.family, param: p.n, kind: `school-${p.topicId.slice(7)}-${p.level}-${p.family}` } };
}

/** Independent arithmetic verifier: substitution, exhaustive bounded searches, and exact integer rounding. */
function mathematicalCheck(task: Task, { topicId, level: l, family: f, n }: Parameters): boolean {
  const a = typeof task.answer === 'string' ? Number(task.answer) : NaN;
  const close = (x: number, y: number) => Number.isFinite(x) && Number.isFinite(y) && Math.abs(x - y) <= 1e-7;
  const all = (expected: number[]) => Array.isArray(task.answer) && task.answer.length === expected.length && expected.every((x, i) => close(Number(task.answer[i]), x));
  const select = (predicate: (x: number) => boolean) => Array.isArray(task.answer) && (task.options ?? []).every(x => task.answer.includes(x) === predicate(Number(x)));
  const largestDivisor = (x: number, y: number) => { for (let k = Math.min(x, y); k > 0; k--) if (x % k === 0 && y % k === 0) return k; return 1; };
  const firstCommon = (values: number[]) => { const stride = Math.max(...values); for (let k = stride; k <= values.reduce((r, v) => r * v, 1); k += stride) if (values.every(v => k % v === 0)) return k; return NaN; };
  const roundIntegerAtoms = (atoms: number, step: number) => { const lower = atoms - atoms % step; return (atoms - lower) * 2 >= step ? lower + step : lower; };
  switch (topicId) {
    case 'school-divisibility':
      if (l === 1 && f === 0) return select(x => Number.isInteger((120 + 12 * n) / x));
      if (l === 1) { const bound = 57 + 7 * n; return Number.isInteger(a) && a % 5 === 0 && a <= bound && a + 5 > bound; }
      if (l === 2 && f === 0) { const prefix = 100 * (1 + n % 7), suffix = n % 10; let digit = 0; while ((prefix + 10 * digit + suffix) % 9 !== 0) digit++; return Number.isInteger(a) && a === digit; }
      if (l === 2) return select(x => Number.isInteger(x / 4) && Number.isInteger(x / 6));
      if (f === 0) { const bound = 220 + 11 * n; let expected = bound; while (expected % 4 !== 0 || expected % 9 !== 0) expected++; return close(a, expected); }
      return Number.isInteger(a) && a >= 0 && a < 8 && (70 + 7 * n - a) % 8 === 0;
    case 'school-gcd-lcm':
      if (l === 1 && f === 0) return close(a, largestDivisor(4 * (n + 4), 6 * (n + 4)));
      if (l === 1) return all([largestDivisor(3 * (n + 5), 5 * (n + 5)), largestDivisor(2 * (n + 7), 7 * (n + 7)), largestDivisor(4 * (n + 9), 9 * (n + 9))]);
      if (l === 2 && f === 0) return close(a, firstCommon([6 * (n + 3), 8 * (n + 3)]));
      if (l === 2) return close(a, largestDivisor(9 * (n + 2), 12 * (n + 2)));
      if (f === 0) { const end = 20 * (n + 2) * (2 + n % 5); let count = 0; for (let t = 1; t <= end; t++) if (t % (4 * (n + 2)) === 0 && t % (10 * (n + 2)) === 0) count++; return close(a, count); }
      return close(a, firstCommon([6 * (n + 2), 8 * (n + 2), 9 * (n + 2)]));
    case 'school-decimals':
      if (l === 1 && f === 0) return (task.options ?? []).includes(key(a)) && (task.options ?? []).every(x => Number(x) <= a);
      if (l === 1) return close(a * 100 - (150 + 11 * n), 90 + 7 * n);
      if (l === 2 && f === 0) return close(a * 100 + (20 + 3 * n), 3 * (120 + 7 * n));
      if (l === 2) return close(a * .5, (35 + 2 * n) / 10);
      if (f === 0) return Number.isInteger(a) && a * 25 <= 1000 + 35 * n && (a + 1) * 25 > 1000 + 35 * n;
      return close(a * (2 + n % 4) * 10 + (13 + 3 * n) * 10, (2 + n % 4) * (11 + n) + (13 + 3 * n) * 10);
    case 'school-rounding':
      if (l === 1 && f === 0) return close(a * 100, roundIntegerAtoms(100 * n + 64, 100));
      if (l === 1) return close(a * 100, roundIntegerAtoms(100 * n + [14, 25, 36, 47, 58, 69, 71, 82][(n - 1) % 8], 10));
      if (l === 2 && f === 0) return close(a * 1000, roundIntegerAtoms(1000 * (10 + n) + 137 + 23 * n, 10));
      if (l === 2) return all([241, 255, 995].map(x => roundIntegerAtoms(1000 * n + x, 100) / 1000));
      if (f === 0) return close(a * 100, roundIntegerAtoms(7 * (2500 + 17 * n), 100));
      return select(x => roundIntegerAtoms(x, 10) === 200 + 10 * n);
    case 'school-sets':
      if (l === 1 && f === 0) return select(x => x === n + 30 || x === n + 32 || x === n + 35);
      if (l === 1) return close(a, [n + 40, n + 42, n + 44, n + 46].length);
      if (l === 2 && f === 0) return select(x => x === n + 10 || x === n + 12 || x === n + 15 || x === n + 17);
      if (l === 2) return select(x => (x - n >= 20 && x - n <= 26 && (x - n) % 2 === 0) && x !== n + 22);
      if (f === 0) { const count = 60 + n, chess = 20 + n, robotics = 17 + n % 7, overlap = 5 + n % 4; let neither = 0; for (let person = 0; person < count; person++) { const first = person < chess; const second = person < overlap || (person >= chess && person < chess + robotics - overlap); if (!first && !second) neither++; } return close(a, neither); }
      return Number.isInteger(a) && a >= 0 && a <= Math.min(25 + n, 24 + 2 * n) && close((25 + n) + (24 + 2 * n) - a, 40 + 2 * n);
    case 'school-absolute-value':
      if (l === 1 && f === 0) return close(a - (3 + n), -(-10 - 2 * n));
      if (l === 1) return all([8 + n, 0, 17 + n]);
      if (l === 2 && f === 0) return a >= 0 && close((a * 10) ** 2, ((35 + 2 * n) - (-20 - n)) ** 2);
      if (l === 2) { const inner = (-4 - n) - (6 + 2 * n); return close(a + 4 + n, inner < 0 ? -inner : inner); }
      if (f === 0) return select(x => (x - (4 * n - 15)) ** 2 < (2 + n % 3) ** 2);
      { const center = 3 * n - 10, radius = n + 2; let count = 0; for (let x = center - radius - 1; x <= center + radius + 1; x++) if ((x - center) ** 2 <= radius ** 2) count++; return close(a, count); }
    case 'school-basic-angles':
      if (l === 1 && f === 0) { const angle = 10 + 5 * n; return a === 1 ? angle > 0 && angle < 90 : a === 2 ? angle === 90 : a === 3 && angle > 90 && angle < 180; }
      if (l === 1) return a > 0 && close(a + 8 + 3 * n, 90);
      if (l === 2 && f === 0) return a > 0 && close(a + 40 + n + 70 + 2 * n, 360);
      if (l === 2) return Array.isArray(task.answer) && task.answer.every((x, i) => Number(x) > 0 && close(Number(x) + [12 + 2 * n, 60 + n, 100 + n][i], 180));
      if (f === 0) { const other = 180 - a; return a > other && other > 0 && close(a - other, 11 + 3 * n); }
      return a > 0 && close(a + a + 40 + 4 * n, 360);
    case 'school-perimeter':
      if (l === 1 && f === 0) return close(a, [n + 8, n + 8, n + 8].reduce((s, v) => s + v, 0));
      if (l === 1) return close(a, [n + 6, n + 6, n + 6, n + 6].reduce((s, v) => s + 2 * v, 0));
      if (l === 2 && f === 0) return close(a * 10, [150 + 7 * n, 70 + 3 * n, 150 + 7 * n, 70 + 3 * n].reduce((s, v) => s + v, 0));
      if (l === 2) return all([[n + 6, n + 6, n + 6, n + 6], [n + 7, n + 7, n + 7], [n + 8, n + 3, n + 8, n + 3]].map(edges => edges.reduce((s, v) => s + v, 0)));
      if (f === 0) return close(a, [n + 16, n + 7, n + 16, n + 7, 3, 3, 3, 3].reduce((s, v) => s + v, 0));
      return a > 0 && close(a + (n + 20) + a + (n + 20), 4 * n + 56);
  }
}

export function schoolReviewCapacity(topicId: string, level: Level = 1): number {
  return parameters(topicId, 1, level) ? capacity : 0;
}

export function generateSchoolReviewTask(topicId: string, serial: number, level: Level = 1): Task | null {
  const p = parameters(topicId, serial, level);
  if (!p) return null;
  const task = create(p), result = validateSchoolReviewTask(task);
  if (!result.valid) throw new Error(result.errors.join('; '));
  return task;
}

/** Reject edits to checked content, including either translation, answers, aids and provenance. */
export function validateSchoolReviewTask(raw: unknown): { valid: boolean; errors: string[] } {
  if (!raw || typeof raw !== 'object') return { valid: false, errors: ['Invalid school review task'] };
  const task = raw as Task, g = task.generation;
  if (!g || g.version !== 'review-2026.2') return { valid: false, errors: ['Unknown school review provenance'] };
  const p = parameters(task.topicId, g.serial, task.level);
  if (!p) return { valid: false, errors: ['Unknown school review topic, level or serial'] };
  const canonical = create(p), issues: string[] = [];
  try { if (JSON.stringify(task) !== JSON.stringify(canonical)) issues.push('School review condition, translation, key, aids or provenance changed'); }
  catch { issues.push('School review task is not serializable'); }
  // Check the canonical key independently even if the submitted structure was damaged.
  if (!mathematicalCheck(canonical, p)) issues.push(`Independent school review math check ${canonical.id}`);
  return { valid: issues.length === 0, errors: issues };
}
